#include <cassert>
#include <iostream>
struct Node { int value; Node* next; };
const Node* CycleEntry(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    // 먼저 고리 안의 만남을 찾습니다. 시작 위치가 같은 것은 세지 않습니다.
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            const Node* fromHead = head;
            // 이제 두 위치를 같은 속도로 옮깁니다.
            while (fromHead != slow) {
                fromHead = fromHead->next;
                slow = slow->next;
            }
            return fromHead;
        }
    }
    return nullptr;
}
int main() {
    Node a{1,nullptr}, b{2,nullptr}, c{3,nullptr}, d{4,nullptr}, e{5,nullptr};
    a.next=&b; b.next=&c; c.next=&d; d.next=&e; e.next=&c;
    assert(CycleEntry(&a)==&c);
    assert(CycleEntry(&c)==&c);
    e.next=nullptr;
    assert(CycleEntry(&a)==nullptr);
    a.next=&a;
    assert(CycleEntry(&a)==&a);
    assert(CycleEntry(nullptr)==nullptr);
    std::cout << "cycle-entry checks passed\n";
}
